import{_ as n,o as t,c as a,a6 as o}from"./chunks/framework.CCKCzdWs.js";const g=JSON.parse('{"title":"Zephyr Scale Cloud","description":"Connect Zephyr Scale Cloud to the dashboard: the region, the API token, the sign-in check and the environment variables.","frontmatter":{"title":"Zephyr Scale Cloud","description":"Connect Zephyr Scale Cloud to the dashboard: the region, the API token, the sign-in check and the environment variables.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/operate/zephyr-scale.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/operate/zephyr-scale.html"}],["meta",{"property":"og:title","content":"Zephyr Scale Cloud | Piwi for Playwright"}],["meta",{"property":"og:description","content":"Connect Zephyr Scale Cloud to the dashboard: the region, the API token, the sign-in check and the environment variables."}]]},"headers":[],"relativePath":"operate/zephyr-scale.md","filePath":"operate/zephyr-scale.md","lastUpdated":1794350813000}'),r={name:"operate/zephyr-scale.md"};function i(h,e,s,c,d,l){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="zephyr-scale-cloud" tabindex="-1">Zephyr Scale Cloud <a class="header-anchor" href="#zephyr-scale-cloud" aria-label="Permalink to &quot;Zephyr Scale Cloud&quot;">​</a></h1><p>Connect Zephyr Scale Cloud, the test management app for Jira, to the dashboard. Piwi sends nothing to Zephyr Scale yet: the connection can be created, checked and tested, and it holds the token in one place, managed by an administrator.</p><p>A connection is instance infrastructure, like an <a href="./integrations.html">issue tracker connection</a>: one row per external system, shared by every project, with its token encrypted at rest with <code>PIWI_SECRET_KEY</code>. Zephyr Scale is never offered as an issue tracker, so a project cannot be bound to it for links or for filing issues.</p><h2 id="connecting-zephyr-scale-cloud" tabindex="-1">Connecting Zephyr Scale Cloud <a class="header-anchor" href="#connecting-zephyr-scale-cloud" aria-label="Permalink to &quot;Connecting Zephyr Scale Cloud&quot;">​</a></h2><ol><li>In Jira, open your profile picture, then <strong>Zephyr API keys</strong>, and create a token. Use a dedicated account, so the token does not end with a person&#39;s access.</li><li><strong>Settings → Integrations → Connect Zephyr Scale Cloud</strong> (administrator only): pick the <strong>Region</strong> your Zephyr Scale Cloud runs in (US, EU, AU or DE), paste the token, and choose <strong>Check</strong>. Then <strong>Save</strong>.</li></ol><p><strong>Check</strong> signs in on the region&#39;s API and lists the projects the token sees, without saving anything. <strong>Test connection</strong> on the saved connection signs in again and records the result on its card. Both give up after about ten seconds, and a host that does not answer in that time is reported as unreachable: check that the server can reach the region&#39;s host through any proxy, firewall or VPN.</p><h2 id="the-region-decides-the-host" tabindex="-1">The region decides the host <a class="header-anchor" href="#the-region-decides-the-host" aria-label="Permalink to &quot;The region decides the host&quot;">​</a></h2><p>Zephyr Scale Cloud runs one API per region, and Piwi calls the host the chosen region names. It never takes a host from the form, so a typed address is ignored and an unknown region is refused. Changing the region of a saved connection asks for the token again, because a token belongs to one region.</p><h2 id="environment-managed-connection" tabindex="-1">Environment-managed connection <a class="header-anchor" href="#environment-managed-connection" aria-label="Permalink to &quot;Environment-managed connection&quot;">​</a></h2><p>Set <code>PIWI_ZEPHYR_API_TOKEN</code>, and optionally <code>PIWI_ZEPHYR_REGION</code> (<code>us</code> by default), to manage the connection from the environment instead. It then shows a lock badge and is read-only in the dashboard: change it by editing the environment and restarting. The token stays in the environment and never enters the database. A region the variable does not name is logged and replaced by <code>us</code>. See <a href="./integrations.html#environment-managed-vs-dashboard-managed">Environment-managed vs dashboard-managed</a> for how the two kinds of connection behave.</p><h2 id="who-can-do-what" tabindex="-1">Who can do what <a class="header-anchor" href="#who-can-do-what" aria-label="Permalink to &quot;Who can do what&quot;">​</a></h2><p>With <a href="./authentication.html">authentication</a> on, creating, checking, testing, editing and deleting a Zephyr Scale connection is administrator-only.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./integrations.html">Integrations</a>: the Jira Cloud connection and how connections are managed</li><li><a href="./production-checklist.html">Production checklist</a>: <code>PIWI_SECRET_KEY</code>, which encrypts the stored token</li><li><a href="/reference/configuration.html#integrations">Configuration reference</a>: the integration variables</li></ul>',14)])])}const u=n(r,[["render",i]]);export{g as __pageData,u as default};
